// ===== EDITE AQUI =====
const CONFIG = {
  // Temas pesquisados no Google Notícias. A IA do app decide quais notícias
  // realmente têm a ver com a empresa — aqui vale ser abrangente.
  palavrasChave: [
    "subestação energia",
    "linhas de transmissão energia",
    "leilão de transmissão Aneel",
    "automação industrial mineração siderurgia",
    "sistema de proteção elétrica relé",
    "usina solar fotovoltaica",
    "NR10 segurança elétrica",
    "comissionamento usina subestação",
  ],
  porTema: 8,          // quantas manchetes recentes de cada tema enviar para a IA avaliar
  diasRecentes: 7,     // só notícias dos últimos N dias
  maxPautas: 3,        // máximo de projetos criados por execução
  canal: "LINKEDIN",   // LINKEDIN ou INSTAGRAM
  appUrl: "http://localhost:3000",
};
// ======================

return CONFIG.palavrasChave.map((palavraChave) => ({
  json: {
    palavraChave,
    rssUrl:
      "https://news.google.com/rss/search?q=" +
      encodeURIComponent(palavraChave + " when:" + CONFIG.diasRecentes + "d") +
      "&hl=pt-BR&gl=BR&ceid=BR:pt-419",
    porTema: CONFIG.porTema,
    diasRecentes: CONFIG.diasRecentes,
    maxPautas: CONFIG.maxPautas,
    canal: CONFIG.canal,
    appUrl: CONFIG.appUrl.replace(/\/+$/, ""),
  },
}));

// Junta as manchetes de todas as buscas numa lista única. A escolha do que vira post
// é feita pela IA no app (endpoint /api/automation/pautas), que conhece a empresa.
const configs = $('Configuração').all().map((i) => i.json);
const respostas = $input.all();

const decode = (s) =>
  s.replace(/<!\[CDATA\[/g, "").replace(/\]\]>/g, "")
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, " ").trim();
const tag = (xml, name) => {
  const inicio = xml.search(new RegExp(`<${name}[ >]`));
  if (inicio < 0) return "";
  const abre = xml.indexOf(">", inicio) + 1;
  const fecha = xml.indexOf(`</${name}>`, abre);
  return fecha < 0 ? "" : decode(xml.slice(abre, fecha));
};
const normalizar = (t) => t.toLowerCase().normalize("NFD").replace(/[^a-z0-9 ]/g, "").replace(/ +/g, " ").trim();

const cfg0 = configs[0] || {};
const limite = Date.now() - (cfg0.diasRecentes || 7) * 24 * 3600 * 1000;
const vistos = new Set();
const candidatos = [];

respostas.forEach((resp, idx) => {
  const cfg = configs[idx] || cfg0;
  const xml = String(resp.json.xml || "");
  const itens = xml.split("<item>").slice(1).map((bloco) => {
    const fonte = tag(bloco, "source");
    let titulo = tag(bloco, "title");
    if (fonte && titulo.endsWith(` - ${fonte}`)) titulo = titulo.slice(0, -(fonte.length + 3)).trim();
    return { titulo, fonte, link: tag(bloco, "link"), data: new Date(tag(bloco, "pubDate")), tema: cfg.palavraChave };
  });

  itens
    .filter((n) => n.titulo && !isNaN(n.data) && n.data.getTime() >= limite)
    .sort((a, b) => b.data - a.data)
    .slice(0, cfg.porTema || 10)
    .forEach((n) => {
      const chave = normalizar(n.titulo);
      if (vistos.has(chave)) return;
      vistos.add(chave);
      candidatos.push({
        titulo: n.titulo,
        fonte: n.fonte,
        link: n.link,
        data: n.data.toLocaleDateString("pt-BR", { timeZone: "America/Sao_Paulo" }),
        tema: n.tema,
      });
    });
});

if (candidatos.length === 0) return [];

return [{
  json: {
    appUrl: cfg0.appUrl,
    body: { candidatos: candidatos.slice(0, 80), maxPautas: cfg0.maxPautas, canal: cfg0.canal },
  },
}];
